    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        #strategy: exact same as course schedule 1, except create a list each time we find a zero degree course that we have not taken before

        pre = {} #dictionary to store all courses that need the current course, course -> list of dependent courses
        deg = {} #course -> number of courses that need to be taken before able to take this course (number of prerequisites it has)
        #taken = set()
        ret = []

        for i in range(numCourses):
            if i not in deg:
                deg[i] = 0

        for i in prerequisites:
            a, b = i[0], i[1]
            if a not in deg:
                deg[a] = 1
            else:
                deg[a] += 1

            if b not in deg:
                deg[b] = 0

            if b not in pre:
                pre[b] = []

            pre[b].append(a)

        print(pre, deg)
        #now check if all courses can be taken
        count = 0 #tracks current number of course that can be taken

        while True:
            #first find a course that has degree value 0, this means it needs no prereqs
            found = False
            course = 0
            for k, v in deg.items():
                if v == 0:
                    found = True
                    deg[k] = -1
                    course = k
                    count += 1
                    ret.append(course)
                    break

            if not found:
                break

            if course in pre: #if this course is a prerequisite for other courses, decrement the count of those other courses
                for i in pre[course]:
                    if deg[i] > 0: #only decrement counter if not used yet or not 0
                        deg[i] -= 1

        if count != numCourses:
            return []
        else:
            return ret

class Solution:
    def findOrder(self, numCourses, prerequisites):
        """
       :type numCourses: int
       :type prerequisites: List[List[int]]
       :rtype: List[int]
       """
        res = []
        graph = {i:set()for i in range(numCourses)}
        for p in prerequisites:
            graph[p[1]].add(p[0])
        # 1: visited, 0 no visited, -1 in progress
        visit = {i:0 for i in range(numCourses)}
        # post-order DFS. The key in toplogical sort
        def dfs(n):
           if visit[n] == 1:
               return True
           if visit[n] == -1:
               return False
           visit[n] = -1
           for neighbor in graph[n]:
               if not dfs(neighbor):
                   return False
           visit[n] = 1
           res.insert(0, n)
           return True
        for i in graph:
           if not dfs(i):
               return [] # there is a cycle
        return res

