    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        if numCourses is 0 or prerequisites is None:
            return []

        graph = {}
        for i in range(numCourses):
            graph[i] = []

        for src, dst in prerequisites:
            graph[src].append(dst)


        results = []
        visited = set()

        def dfs(node):
            if node in visited:
                return False
            if node in results:
                return True

            visited.add(node)

            for nei in sorted(graph[node]):
                if not dfs(nei):
                    return False
                graph[node].remove(nei)

            visited.remove(node)

            if node not in results:
                results.append(node)

            return True

        for i in range(numCourses):
            if not dfs(i):
                return []

        return results

