class Solution:
    courseList = []
    identified = []
    courseOrder = []
    coursesWithPrerequisites = set()

    def handlePrerequisites(self, course: "Course") -> bool:
        print(f"handling prerequisites of course {course.courseNo}")
        if course in self.identified:
            return False
        elif course in self.courseOrder:
            return True
        else:
            self.identified.append(course)
            for p in course.prerequisites:
                if not self.handlePrerequisites(p):
                    return False
            print(f"Adding course {course.courseNo} to course order")
            self.courseOrder.append(course)
            self.identified.remove(course)
            return True

    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        self.courseList = []
        self.identified = []
        self.courseOrder = []
        self.coursesWithPrerequisites = set()

        for i in range(numCourses):
            self.courseList.append(Course(i))

        for p in prerequisites:
            self.coursesWithPrerequisites.add(p[0])
            self.courseList[p[0]].prerequisites.append(self.courseList[p[1]])

        print(f"After init, courses with prerequisites are: {self.coursesWithPrerequisites}")

        for c in [self.courseList[i] for i in self.coursesWithPrerequisites]:
            print(f"Considering course {c.courseNo}, which has prerequisites")
            if c in self.courseOrder:
                continue
            if not self.handlePrerequisites(c):
                return []

        for c in self.courseList:
            if c in self.courseOrder:
                continue
            if not self.handlePrerequisites(c):
                return []

        return [c.courseNo for c in self.courseOrder]

