        result = []
        while q:
            node = q.popleft()
            # if node in visit:
            #     return []
            visit.add(node)
            result.append(node)
            for child in graph[node]:
                inbounds[child] -= 1
                if inbounds[child] == 0:
                    q.append(child)
        return result if len(visit) == numCourses else []

