class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        #convert to graph
        #topsort
        nodes = [[] for _ in range(numCourses)]
        for edge in prerequisites:
            nodes[edge[0]].append(edge[1])
        ingoing = [0 for _ in range(numCourses) ]
        for node in nodes:
            for v in node:
                ingoing[v] += 1
        queue = deque()
        for i in range(len(ingoing)):
            if ingoing[i] == 0:
                queue.append(i)

        res = []

        while(queue):
           v = queue.popleft()
           res.append(v)
           for i in nodes[v]:
               ingoing[i] -= 1
               if ingoing[i] == 0 :
                   queue.append(i) 

        if(len(res) == numCourses):
            return res[::-1]

        return []

