class Solution(object):
    def findRedundantConnection(self, edges):
        """
        :type edges: List[List[int]]
        :rtype: List[int]
        """
        adj = {}
        for i in range(1, len(edges)+1):
            adj[i] = []

        for edge in edges:
            visited = {}
            curr = edge[0]
            dest = edge[1]

            conect = [False]
            isConnected(curr, dest, adj, visited,conect)
            if conect[0]== True:
                return edge
            adj[curr].append(dest)
            adj[dest].append(curr)
        return None

def isConnected(curr, dest, adj, visited,conect):
    if adj == {}:
