class Vertex(object):
    def __init__(self, val):
        self.val = val
        self.neighbors = []

class Solution(object):
    def findRedundantConnection(self, edges):
        """
        :type edges: List[List[int]]
        :rtype: List[int]
        """
        visited = set()
        nodeMap = {}
        for edge in edges:
            a = edge[0]
            b = edge[1]
            if a not in nodeMap:
                nodeMap[a] = Vertex(a)
            if b not in nodeMap:
                nodeMap[b] = Vertex(b)
            nodeMap[a].neighbors.append(nodeMap[b])
            nodeMap[b].neighbors.append(nodeMap[a])
        self.cyclePath = []
        cycleEdges = set()
        for vertex in nodeMap.values():
            if self.findCycle(vertex, [], set(), None, visited):
                for i in range(1, len(self.cyclePath)):
                    cycleEdges.add( (self.cyclePath[i], self.cyclePath[i - 1]) )
                cycleEdges.add((self.cyclePath[-1], self.cyclePath[0]))
                break

        for edge in reversed(edges):
            edge1 = tuple(edge)
            edge2 = tuple(reversed(edge))
            if edge1 in cycleEdges:
                return edge
            if edge2 in cycleEdges:
                return edge 
        return [1, 1]

    def findCycle(self, vertex, path, pathSet, cameFrom, visited):
        if vertex in visited:
            return False
        if vertex in pathSet:
            self.cyclePath = path[path.index(vertex.val):]
            return True
        path.append(vertex.val)
        pathSet.add(vertex)
        for neighbor in vertex.neighbors:
            if neighbor != cameFrom:
                if self.findCycle(neighbor, path, pathSet, vertex, visited):
                    return True
        path.pop()
        pathSet.remove(vertex)
        visited.add(vertex)
        return False

