class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        # [10,9,2,5,3,7,101,18]
        # [     1 2 2 3   4  4]
        a = [] # [n, seq]

        def insert(n, seq):
            nonlocal a
            if len(a) == 0:
                a.append([n, seq])
                return
            if seq >= a[0][1]:
                a = [[n, seq]] + a
                return
            if seq <= a[-1][1]:
                a.append([n, seq])
                return

            l, r = 0, len(a) - 1
            while r - l > 1:
                mid = (l + r) // 2
                if a[mid][1] == seq:
                    l = r = mid
                    break
                elif a[mid][1] > seq:
                    l = mid
                else:
                    r = mid
            if l == r:
                a = a[:l] + [[n, seq]] + a[r:]
            else:
                a = a[:l+1] + [[n, seq]] + a[r:]

        for n in nums:
            seq = 1
            an = ''
            for an, aseq in a:
                if an < n:
                    seq = aseq + 1
                    break
            insert(n, seq)

        return a[0][1]

