class Solution:
    def search_left(self, nums, target):
        left, right = 0, len(nums) - 1
        index = -1
        while left <= right:
            middle = (left + right) // 2
            if nums[middle] == target:
                index = middle
                right = middle - 1
            elif nums[middle] < target:
                left = middle + 1
            else:
                right = middle - 1
        return index

    def search_right(self, nums, target):
        left, right = 0, len(nums) - 1
        index = -1
        while left <= right:
            middle = (left + right) // 2
            if nums[middle] == target:
                index = middle
                left = middle + 1
            elif nums[middle] < target:
                left = middle + 1
            else:
                right = middle - 1
        return index        

    def searchRange(self, nums: List[int], target: int) -> List[int]:
        left = self.search_left(nums, target)
        right = self.search_right(nums, target)
        return [left, right]

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def binary_search(nums, target, find_start):
            index = -1
            l, r = 0, len(nums) - 1
            while l <= r:
                mid = l + (r - l) // 2
                if nums[mid] == target:
                    index = mid
                    if find_start:
                        r = mid - 1 
                    else:
                        l = mid + 1 
                elif nums[mid] < target:
                    l = mid + 1
                else:
                    r = mid - 1
            return index
        start = binary_search(nums, target, find_start=True)
        end = binary_search(nums, target, find_start=False)
        return [start, end]

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:

        lower_bound = self.findBound(nums, target, True)
        if (lower_bound == -1):
            return [-1, -1]

        upper_bound = self.findBound(nums, target, False)

        return [lower_bound, upper_bound]

    def findBound(self, nums: List[int], target: int, isFirst: bool) -> int:

        N = len(nums)
        begin, end = 0, N - 1
        while begin <= end:
            mid = int((begin + end) / 2)    

            if nums[mid] == target:

                if isFirst:
                    # This means we found our lower bound.
                    if mid == begin or nums[mid - 1] < target:
                        return mid

                    # Search on the left side for the bound.
                    end = mid - 1
                else:

                    # This means we found our upper bound.
