from functools import lru_cache

@lru_cache(None)
def fib_recursive(n: int) -> int:
    """
    Calculate the nth Fibonacci number recursively with memoization.
    The Fibonacci sequence is defined as:
      F(0) = 0, F(1) = 1
      F(n) = F(n-1) + F(n-2) for n >= 2
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib_recursive(n - 1) + fib_recursive(n - 2)

from typing import List

def find_median_sorted_arrays(nums1: List[int], nums2: List[int]) -> float:
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1
    x, y = len(nums1), len(nums2)
    low, high = 0, x

    while low <= high:
        partitionX = (low + high) // 2
        partitionY = (x + y + 1) // 2 - partitionX

        maxX = float('-inf') if partitionX == 0 else nums1[partitionX - 1]
        minX = float('inf') if partitionX == x else nums1[partitionX]

        maxY = float('-inf') if partitionY == 0 else nums2[partitionY - 1]
        minY = float('inf') if partitionY == y else nums2[partitionY]

        if maxX <= minY and maxY <= minX:
            if (x + y) % 2 == 0:
                return (max(maxX, maxY) + min(minX, minY)) / 2
            else:
                return max(maxX, maxY)
        elif maxX > minY:
            high = partitionX - 1
        else:
            low = partitionX + 1

    raise ValueError("Input arrays are not sorted")

def search_rotated_sorted_array(array, target):
    """
    This function returns the index of the target in the rotated sorted array if found, otherwise -1.
    """
    start, end = 0, len(array) - 1

    while start <= end:
        mid = (start + end) // 2

        if array[mid] == target:
            return mid

        if array[start] <= array[mid]:  # left half is sorted
            if array[start] <= target < array[mid]:
                end = mid - 1
            else:
                start = mid + 1
        else:  # right half is sorted
            if array[mid] < target <= array[end]:
                start = mid + 1
            else:
                end = mid - 1

    return -1

