def search_rotated_array(arr, target):
    """
    Searches for the target in a rotated sorted array and returns its index or -1 if not found.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] == target:
            return mid

        if arr[left] <= arr[mid]:  # Left half is sorted
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # Right half is sorted
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

from bisect import bisect_left

def longest_increasing_subsequence(A):
    """
    Computes the length of the longest increasing subsequence in an array of integers.
    :param A: List[int] - List of integers
    :return: int - Length of the longest increasing subsequence
    """
    if not A:
        return 0
    lis = []
    for num in A:
        pos = bisect_left(lis, num)
        if pos == len(lis):
            lis.append(num)
        else:
            lis[pos] = num
    return len(lis)

