def last_occurrence(array: List[int], target: int) -> int:
    left, right = 0, len(array) - 1
    result = -1

    while left <= right:
        mid = left + (right - left) // 2
        if array[mid] == target:
            result = mid
            left = mid + 1
        elif array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result

from typing import List, Tuple
from collections import deque, defaultdict

def find_course_order(num_courses: int, prerequisites: List[Tuple[int, int]]) -> List[int]:
    """
    Determine the order of courses based on prerequisites.
    If a cycle is detected, return an empty list.
    """
    in_degree = {i: 0 for i in range(num_courses)}
    graph = defaultdict(list)

    for course, prereq in prerequisites:
        in_degree[course] += 1
        graph[prereq].append(course)

    queue = deque([i for i in range(num_courses) if in_degree[i] == 0])
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) == num_courses:
        return order
    else:
        return []

def count_ways(n: int) -> int:
    """
    Computes the number of distinct ways to reach the nth step.
    This is essentially finding the (n+1)th Fibonacci number.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 1

    a, b = 1, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

