def binary_search(arr, target):
    if not arr:
        return -1

    left, right = 0, len(arr) - 1
    ascending = arr[left] < arr[right]

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        elif ascending:
            if target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if target > arr[mid]:
                right = mid - 1
            else:
                left = mid + 1

    return -1

