import sys
def minMoves ( arr ) :
    N = len ( arr )
    if ( N <= 2 ) :
        return 0
    ans = sys . maxsize
    for i in range ( - 1 , 2 ) :
        for j in range ( - 1 , 2 ) :
            num1 = arr [ 0 ] + i
            num2 = arr [ 1 ] + j
            flag = 1
            moves = abs ( i ) + abs ( j )
            for idx in range ( 2 , N ) :
                num = num1 + num2
                if ( abs ( arr [ idx ] - num ) > 1 ) :
                    flag = 0
                else :
                    moves += abs ( arr [ idx ] - num )
                num1 = num2
                num2 = num
            if ( flag ) :
                ans = min ( ans , moves )
    if ( ans == sys . maxsize ) :
        return - 1
    return ans
